rf_field() }}<button class="btn btn-mini">Toggle</button></form> <form method="post" action="{{ url('/webhook-endpoints/'.$hook->id.'/delete') }}" style="display:inline">{{ csrf_field() }}<button class="btn btn-mini btn-danger" onclick="return confirm('Delete this webhook and its history?')">Delete</button></form></td></tr>@empty<tr><td>No webhooks configured.</td></tr>@endforelse</table></div></div></div><div class="box"><div class="box-header"><h2>Webhook delivery history</h2></div><div class="box-content"><table class="table table-striped table-bordered"><thead><tr><th>Time</th><th>Endpoint</th><th>Event</th><th>Delivery ID</th><th>Status</th><th>Response</th><th>Duration</th></tr></thead><tbody>@forelse($deliveries as $delivery)<tr><td>{{ date('M j, Y g:i:s A',strtotime($delivery->created_at)) }}</td><td>{{ $delivery->webhook_name }}</td><td>{{ $delivery->event_name }}</td><td><code>{{ $delivery->delivery_id }}</code></td><td><span class="label {{ $delivery->status==='delivered'?'label-success':'label-important' }}">{{ ucfirst($delivery->status) }}</span></td><td>{{ $delivery->response_status ?: $delivery->error }}</td><td>{{ $delivery->duration_ms }} ms</td></tr>@empty<tr><td colspan="7">No webhook deliveries yet.</td></tr>@endforelse</tbody></table></div></div><div class="alert alert-info"><strong>API base URL:</strong> <code>{{ url('/api/v1') }}</code>. Send keys as <code>Authorization: Bearer YOUR_KEY</code>. Webhooks are signed with HMAC-SHA256 in <code>X-Ecommerce-Signature</code>.</div></div>
